using System.ComponentModel;
using System.Text.Json;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using OpenAI;

// ── Bootstrap ──────────────────────────────────────────────────────────────
var builder = Host.CreateApplicationBuilder(args);
builder.Logging.SetMinimumLevel(LogLevel.Warning);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY env-var or AI:ApiKey in config.");

const string modelId = "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(cb => cb
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

builder.Services.AddSingleton<Notepad>();
builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddHostedService<ResearchWorker>();

var host = builder.Build();
await host.RunAsync();

// ── Notepad — simple in-memory note store ──────────────────────────────────
public sealed class Notepad
{
    private readonly List<NoteEntry> _notes = [];

    public record NoteEntry(string Title, string Content, DateTime Timestamp);

    public void Add(string title, string content)
        => _notes.Add(new NoteEntry(title, content, DateTime.UtcNow));

    public IReadOnlyList<NoteEntry> GetAll() => _notes.AsReadOnly();
}

// ── Tools exposed to the agent ─────────────────────────────────────────────
public sealed class ResearchTools(Notepad notepad, ILogger<ResearchTools> logger)
{
    [Description("Search the web for a query and return relevant results. Use this to find information about a topic.")]
    public static async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        // Uses the free DuckDuckGo instant-answer API (no key required).
        using var http = new HttpClient();
        http.DefaultRequestHeaders.UserAgent.ParseAdd("ResearchAgent/1.0");

        var url = $"https://html.duckduckgo.com/html/?q={Uri.EscapeDataString(query)}";
        var html = await http.GetStringAsync(url);

        // Extract result snippets from the HTML response.
        var results = new List<string>();
        const string snippetStart = "result__snippet";
        var idx = 0;
        while (results.Count < 6 && (idx = html.IndexOf(snippetStart, idx, StringComparison.Ordinal)) >= 0)
        {
            var gt = html.IndexOf('>', idx);
            var lt = html.IndexOf('<', gt + 1);
            if (gt >= 0 && lt > gt)
            {
                var text = System.Net.WebUtility.HtmlDecode(html[( gt + 1)..lt]).Trim();
                if (text.Length > 0)
                    results.Add(text);
            }
            idx = lt > 0 ? lt : idx + 1;
        }

        return results.Count > 0
            ? string.Join("\n---\n", results)
            : "No results found. Try a different query.";
    }

    [Description("Save a research note with a title and content. Use this to record important findings.")]
    public string SaveNote(
        [Description("Short descriptive title for the note")] string title,
        [Description("The content of the note")] string content)
    {
        notepad.Add(title, content);
        logger.LogInformation("Note saved: {Title}", title);
        return $"Note '{title}' saved successfully.";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        var notes = notepad.GetAll();
        if (notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n\n", notes.Select((n, i) =>
            $"[{i + 1}] {n.Title} ({n.Timestamp:u})\n{n.Content}"));
    }
}

// ── Hosted service that drives the agent ───────────────────────────────────
public sealed class ResearchWorker(
    IChatClient chatClient,
    ResearchTools tools,
    Notepad notepad,
    IHostApplicationLifetime lifetime,
    ILogger<ResearchWorker> logger) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken ct)
    {
        Console.WriteLine("╔══════════════════════════════════════════╗");
        Console.WriteLine("║       🔍  Research Agent  (MAF)         ║");
        Console.WriteLine("╚══════════════════════════════════════════╝");
        Console.WriteLine();

        Console.Write("Enter a research topic: ");
        var topic = Console.ReadLine()?.Trim();
        if (string.IsNullOrEmpty(topic))
        {
            Console.WriteLine("No topic provided. Exiting.");
            lifetime.StopApplication();
            return;
        }

        Console.WriteLine($"\nResearching: {topic}\n");

        // Build the agent with tools
        var agent = new ChatClientAgent(chatClient, "ResearchAgent")
        {
            Instructions = """
                You are a research agent. Your job is to thoroughly research a topic by:
                1. Searching the web multiple times with varied queries to gather diverse information.
                2. Saving important findings as notes using the SaveNote tool.
                3. After gathering enough information (at least 3-4 searches and notes),
                   retrieve your notes and produce a well-structured summary.

                Be thorough but concise. Cite key facts you discover.
                Always end with a final comprehensive summary of your research.
                """,
        };

        agent.Tools.AddFromObject(tools);

        var history = new List<ChatMessage>
        {
            new(ChatRole.User,
                $"Research the following topic thoroughly and summarize your findings: {topic}"),
        };

        var invokeOptions = new AgentInvokeOptions
        {
            MaximumIterations = 15,
        };

        try
        {
            await foreach (var message in agent.InvokeStreamingAsync(
                history, invokeOptions, ct))
            {
                if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
                {
                    Console.Write(message.Text);
                }
            }

            Console.WriteLine("\n");

            // Print collected notes
            var allNotes = notepad.GetAll();
            if (allNotes.Count > 0)
            {
                Console.WriteLine($"📝 {allNotes.Count} note(s) saved during research:");
                foreach (var note in allNotes)
                    Console.WriteLine($"   • {note.Title}");
            }
        }
        catch (Exception ex)
        {
            logger.LogError(ex, "Agent execution failed");
            Console.WriteLine($"\nError: {ex.Message}");
        }

        Console.WriteLine();
        lifetime.StopApplication();
    }
}

