         Console.WriteLine("╚══════════════════════════════════════════╝");
         Console.WriteLine();

         Console.Write("Enter a research topic: ");
         var topic = Console.ReadLine()?.Trim();
         if (string.IsNullOrEmpty(topic))
         {
             Console.WriteLine("No topic provided. Exiting.");
             lifetime.StopApplication();
             return;
         }

         Console.WriteLine($"\nResearching: {topic}\n");

         // Create AI tools from the ResearchTools instance
         var aiTools = new List<AITool>
         {
             AIFunctionFactory.Create(ResearchTools.SearchWeb),
             AIFunctionFactory.Create(tools.SaveNote),
             AIFunctionFactory.Create(tools.GetNotes),
         };

         // Build the agent with tools
         var agent = new ChatClientAgent(
             chatClient,
             name: "ResearchAgent",
             description: "An agent that researches topics by searching the web and taking notes.",
             instructions: """
                 You are a research agent. Your job is to thoroughly research a topic by:
                 1. Searching the web multiple times with varied queries to gather diverse information.
                 2. Saving important findings as notes using the SaveNote tool.
                 3. After gathering enough information (at least 3-4 searches and notes),
                    retrieve your notes with GetNotes and produce a well-structured summary.

                 Be thorough but concise. Cite key facts you discover.
                 Always end with a final comprehensive summary of your research.
                 """,
             tools: aiTools);

         // Create a session for the agent
         var session = await agent.CreateSessionAsync(cancellationToken: ct);

         try
         {
             // Stream the agent's response
             await foreach (var update in agent.RunStreamingAsync(
                 $"Research the following topic thoroughly and summarize your findings: {topic}",
                 session,
                 cancellationToken: ct))
             {
                 if (!string.IsNullOrEmpty(update.Text))
                 {
                     Console.Write(update.Text);
                 }
             }

             Console.WriteLine("\n");

             // Print collected notes
             var allNotes = notepad.GetAll();
             if (allNotes.Count > 0)
             {
                 Console.WriteLine($"📝 {allNotes.Count} note(s) saved during research:");
                 foreach (var note in allNotes)
                     Console.WriteLine($"   • {note.Title}");
             }
         }
         catch (Exception ex)
         {
             logger.LogError(ex, "Agent execution failed");
             Console.WriteLine($"\nError: {ex.Message}");
         }

         Console.WriteLine();
         lifetime.StopApplication();
     }
 }
